{
  "case_id": "xsu_sg_002_permanence_requirement",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret siger direkte, at der ikke er noget krav om, at tilstanden skal have været varig eller kronisk fra begyndelsen. Det er i strid med vejledningen, hvor udgangspunktet er, at man ikke er berettiget, hvis tilstanden ikke fra debut kan betragtes som varig eller kronisk. Her er omkring et års varighed og symptomer i mindst et år før ansøgning udgangspunktet. Rubrikken nævner netop fejlen, at tilstanden altid skal være kronisk fra debut, og dens modstykke. Svaret nævner heller ikke étårsudgangspunktet og ikke tidsbegrænset tillæg ved sandsynliggjort varighed. Desuden kan en ny tilstand opfylde kravet allerede ved lægelig forventning om langvarighed, hvilket ikke er den beskrevne regel."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "To af fire kritiske elementer mangler: (1) omkring et år og som udgangspunkt symptomer eller følger i mindst et år før ansøgningen, og (2) tidsbegrænset tillæg, når varighed er sandsynliggjort men ikke endeligt fastslået. Svaret nævner ikke, at varigheden gælder art og grad. Det nævner heller ikke eksplicit, at bedring heller ikke må forventes ved behandling. 'Væsentligt bedre' nævnes kun for midlertidige tilstande."
    },
    "c03_direct_relevance": {
      "label": "not_met",
      "reason": "Svaret behandler varighed og spørgsmålet om ikke-varig fra begyndelsen, men besvarer andendelen forkert. Det udelader étårsreglen og mulighed for tidsbegrænset tillæg, og erstatter dem med en generel 'søg igen'-vejledning. Der er derfor ikke svaret på alle væsentlige dele."
    },
    "c04_source_traceability": {
      "label": "met",
      "reason": "Svaret henviser til en identificerbar kilde, SU's information om handicaptillæg (su.dk). Det angiver dog ikke konkrete bestemmelser."
    },
    "c05_source_validity": {
      "label": "not_met",
      "reason": "Den angivne kilde er et generelt link til su.dk/handicaptillaeg. Det er ikke blandt de frosne kilder (vejledning, SU-lov, bekendtgørelse), så der er ikke belæg for, at den er aktuel og omfattet af kildeafgrænsningen. Den er ikke en konkret autoritativ bestemmelse."
    },
    "c06_claim_source_support": {
      "label": "not_met",
      "reason": "De frosne passager støtter ikke de centrale påstande. Påstanden om, at der ikke er krav om varig eller kronisk tilstand fra begyndelsen, modsiges af vejledningen. Ellers findes der ikke passager, der peger på 'søg igen' eller 'nye oplysninger', og et generelt link kan ikke støtte de konkrete påstande."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer uunderbyggede regler: at en nylig opstået tilstand kan opfylde kravet ved lægelig forventning om langvarighed, og at man kan søge igen eller sende nye oplysninger, hvis forløbet viser sig langvarigt. Desuden er 'forventes at bestå i længere tid eller på ubestemt tid' en lempeligere definition end vejledningens 'ikke væsentligt bedre inden for en længere årrække'."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "De krævede forbehold mangler: 'som udgangspunkt', 'omkring et år', at tiden alene ikke afgør varigheden, og at tidsbegrænset tillæg forudsætter sandsynliggjort varighed. Svaret bevarer ikke det centrale udgangspunkt om, at man ikke er berettiget, hvis tilstanden ikke fra debut er varig eller kronisk."
    },
    "c09_reasoning_coherence": {
      "label": "not_met",
      "reason": "Svaret er internt uklart: det afviser et krav om varighed fra begyndelsen, men antager samtidig, at midlertidig tilstand som udgangspunkt ikke opfylder kravet, og at man kan søge igen. Det forklarer ikke, hvordan en ikke-varig tilstand bliver varig efter tid, så konklusionen følger ikke af vejledningens logik."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Svaret formulerer 'Der er ikke et krav' absolut, selv om vejledningen kun udtrykker et udgangspunkt for, at tilstanden skal være varig fra debut eller have et års varighed. Det vender dermed udgangspunktet om. 'Udgangspunktet' er bevaret for midlertidige tilstande, men uden det rigtige indhold."
    }
  },
  "xhaile_coverage": {
    "A9": {
      "label": "partial",
      "reason": "Svaret behandler varighed som en forudsætning, men gengiver ikke definitionen korrekt (ingen væsentlig bedring inden for en længere årrække, heller ikke ved behandling), og det nævner ikke art og grad."
    },
    "A12": {
      "label": "no",
      "reason": "Svaret nævner ikke reglen om omkring et års varighed og symptomer i mindst et år før ansøgning. Det modsiger i stedet vejledningens udgangspunkt, da det siger, at der ikke er krav om varig eller kronisk tilstand fra begyndelsen."
    }
  },
  "overall_notes": "Svaret rammer den generelle idé om varighed, men afviser fejlagtigt vejledningens udgangspunkt om debut/ét år og udelader tidsbegrænset tillæg ved sandsynliggjort varighed. Det henviser kun til et generelt link, og flere påstande har ikke støtte i det frosne materiale."
}

